import type { Metadata } from 'next';
import { CONTACT, SITE_CONFIG } from '@/lib/constants';

interface MetadataOptions {
  title: string;
  description: string;
  path?: string;
  image?: string;
}

export function createMetadata({ title, description, path = '/', image = '/logo.png' }: MetadataOptions): Metadata {
  const url = new URL(path, SITE_CONFIG.url).toString();
  return {
    title,
    description,
    alternates: { canonical: url },
    openGraph: { title, description, url, siteName: SITE_CONFIG.name, locale: 'en_IN', type: 'website', images: [{ url: image, alt: SITE_CONFIG.name }] },
    twitter: { card: 'summary_large_image', title, description, images: [image] },
  };
}

export function createOrganizationSchema() {
  return {
    '@context': 'https://schema.org',
    '@type': 'RealEstateAgent',
    name: SITE_CONFIG.name,
    description: SITE_CONFIG.description,
    url: SITE_CONFIG.url,
    logo: `${SITE_CONFIG.url}/logo.png`,
    telephone: `+${CONTACT.phoneRaw}`,
    email: CONTACT.email,
    founder: { '@type': 'Person', name: SITE_CONFIG.founder },
    address: { '@type': 'PostalAddress', addressLocality: 'Lucknow', addressRegion: 'Uttar Pradesh', addressCountry: 'IN' },
    areaServed: { '@type': 'City', name: 'Lucknow' },
  };
}

export function createWebSiteSchema() {
  return {
    '@context': 'https://schema.org',
    '@type': 'WebSite',
    name: SITE_CONFIG.name,
    url: SITE_CONFIG.url,
    potentialAction: { '@type': 'SearchAction', target: `${SITE_CONFIG.url}/properties?query={search_term_string}`, 'query-input': 'required name=search_term_string' },
  };
}